import { useGesture } from '@use-gesture/react';
import { PickD3Scale, TimeDomain } from '@visx/scale';
import React from 'react';

import { TimeBottomAxis } from '../../../core/components/axes/components/TimeBottomAxis.js';
import { ChartGrid } from '../../../core/components/chart-grid/ChartGridRoot.js';
import { usePanning } from '../../../core/components/zoom/hooks/usePanning.js';
import { cursorStyle } from '../../../core/components/zoom/ZoomCursors.sty.js';
import {
  useCurrentDomainState,
  useSetState,
} from '../../hooks/store/selectors.js';
import { useChartInteractions } from '../../hooks/useChartInteractions.js';
import { useTimeseriesTickAxis } from '../../hooks/useTimeseriesTickAxis.js';
import { useXAxisConfig } from '../../hooks/useXAxisConfig.js';
import { useXScales } from '../../hooks/useXScale.js';
import { AREAS } from '../../types/timeseries-grid-area-rules.js';

/**
 * The bottom axis component with default values already set
 */
export function TimeseriesTimeBottomAxisArea() {
  const xAxisConfig = useXAxisConfig();
  const { currentScale: xScale, initialScale } = useXScales();
  const setState = useSetState();
  const { onZoomChange, pan } = useChartInteractions();
  const currentDomain = useCurrentDomainState();
  const isChartWithZoom = Boolean(currentDomain);
  const isPanEnabled = pan?.enabled && isChartWithZoom;
  const { bottom } = useTimeseriesTickAxis() ?? {};
  const hasTicks = Boolean(bottom?.ticks.length);

  const axisRef = React.useRef<HTMLDivElement>(null);

  function handlePan(domain: TimeDomain) {
    setState((prev) => ({
      ...prev,
      currentDomain: domain,
      zoom: { ...prev.zoom, zoomBehavior: 'panning' },
    }));
  }

  function handlePanEnd([min, max]: Date[]) {
    onZoomChange?.(min, max, 'panning');
  }

  const { onDrag, onDragEnd } = usePanning({
    initialXScale: initialScale as PickD3Scale<'time'>,
    xScale: xScale as PickD3Scale<'time'>,
    onPanning: handlePan,
    onPanningEnd: handlePanEnd,
  });

  useGesture(
    {
      onDrag,
      onDragEnd,
    },
    {
      target: axisRef,
      eventOptions: { passive: false },
      drag: { filterTaps: true, pointer: { buttons: [1, 4] } },
      enabled: isPanEnabled,
    },
  );

  return hasTicks && xScale ? (
    <ChartGrid.GridArea gridArea={AREAS.bottomAxis}>
      {({ availableWidth, availableHeight }) => (
        <div
          ref={axisRef}
          className={cursorStyle({ isPanEnabled })}
          data-testid={'timeseries-time-axis'}
        >
          <TimeBottomAxis
            ticks={bottom!.ticks}
            formattedTicks={bottom!.formattedTicks}
            scale={xScale}
            containerHeight={availableHeight}
            containerWidth={availableWidth}
            label={xAxisConfig?.label}
          />
        </div>
      )}
    </ChartGrid.GridArea>
  ) : null;
}

TimeseriesTimeBottomAxisArea['displayName'] = 'TimeseriesValueBottomAxisArea';
